import 'dart:convert';import 'package:flutter/foundation.dart';import 'package:hive/hive.dart';import '../../../core/mesh/mesh_message.dart';/// Chat data service for storing and retrieving mesh conversations.class MeshChatService {  static const String _messagesBox = 'catus_messages';  static const String _conversationsBox = 'catus_conversations';  Box<String>? _msgBox;  Box<String>? _convBox;  Future<void> initialize() async {    _msgBox = await Hive.openBox<String>(_messagesBox);    _convBox = await Hive.openBox<String>(_conversationsBox);  }  /// Save a message to local storage  Future<void> saveMessage(MeshMessage message) async {    // Key: conversationId_messageId    final convId = _getConversationId(message.senderId, message.recipientId);    final key = '${convId}_${message.id}';    await _msgBox?.put(key, jsonEncode(message.toJson()));    // Update conversation preview    await _updateConversation(convId, message);  }  /// Get all messages in a conversation  List<MeshMessage> getMessages(String myId, String contactId) {    final convId = _getConversationId(myId, contactId);    final box = _msgBox;    if (box == null) return [];    final messages = <MeshMessage>[];    for (final key in box.keys) {      if ((key as String).startsWith(convId)) {        final json = box.get(key);        if (json != null) {          messages.add(MeshMessage.fromJson(jsonDecode(json)));        }      }    }    messages.sort((a, b) => a.timestamp.compareTo(b.timestamp));    return messages;  }  /// Get all conversations with last message preview  List<ConversationPreview> getConversations() {    final box = _convBox;    if (box == null) return [];    return box.values        .map((json) => ConversationPreview.fromJson(jsonDecode(json)))        .toList()      ..sort((a, b) => b.lastMessageTime.compareTo(a.lastMessageTime));  }  /// Update message status  Future<void> updateMessageStatus(      String senderId, String recipientId, String messageId, MessageStatus status) async {    final convId = _getConversationId(senderId, recipientId);    final key = '${convId}_$messageId';    final json = _msgBox?.get(key);    if (json == null) return;    final message = MeshMessage.fromJson(jsonDecode(json));    final updated = message.copyWith(status: status);    await _msgBox?.put(key, jsonEncode(updated.toJson()));  }  /// Get unread count for a contact  int getUnreadCount(String myId, String contactId) {    final messages = getMessages(myId, contactId);    return messages.where((m) =>        m.senderId != myId && m.status != MessageStatus.read).length;  }  /// Mark all messages from a contact as read  Future<void> markAsRead(String myId, String contactId) async {    final convId = _getConversationId(myId, contactId);    final box = _msgBox;    if (box == null) return;    for (final key in box.keys) {      if ((key as String).startsWith(convId)) {        final json = box.get(key);        if (json == null) continue;        final msg = MeshMessage.fromJson(jsonDecode(json));        if (msg.senderId != myId && msg.status != MessageStatus.read) {          final updated = msg.copyWith(status: MessageStatus.read);          await box.put(key, jsonEncode(updated.toJson()));        }      }    }  }  /// Delete a conversation  Future<void> deleteConversation(String myId, String contactId) async {    final convId = _getConversationId(myId, contactId);    // Delete all messages    final keys = _msgBox?.keys.where((k) => (k as String).startsWith(convId)).toList() ?? [];    for (final key in keys) {      await _msgBox?.delete(key);    }    // Delete conversation preview    await _convBox?.delete(convId);  }  /// Clear everything (panic wipe)  Future<void> clearAll() async {    await _msgBox?.clear();    await _convBox?.clear();  }  // Generate a consistent conversation ID from two device IDs  String _getConversationId(String id1, String id2) {    final sorted = [id1, id2]..sort();    return sorted.join('_');  }  // Update conversation preview  Future<void> _updateConversation(String convId, MeshMessage message) async {    final existing = _convBox?.get(convId);    int unread = 0;    if (existing != null) {      final prev = ConversationPreview.fromJson(jsonDecode(existing));      unread = prev.unreadCount;    }    final preview = ConversationPreview(      conversationId: convId,      contactId: message.senderId,      contactName: message.senderName,      lastMessage: message.content,      lastMessageTime: message.timestamp,      unreadCount: unread + 1,      channel: message.channel,    );    await _convBox?.put(convId, jsonEncode(preview.toJson()));  }  Future<void> dispose() async {    await _msgBox?.close();    await _convBox?.close();  }}/// Conversation preview for the chat listclass ConversationPreview {  final String conversationId;  final String contactId;  final String contactName;  final String lastMessage;  final DateTime lastMessageTime;  final int unreadCount;  final String channel;  ConversationPreview({    required this.conversationId,    required this.contactId,    required this.contactName,    required this.lastMessage,    required this.lastMessageTime,    required this.unreadCount,    required this.channel,  });  factory ConversationPreview.fromJson(Map<String, dynamic> json) {    return ConversationPreview(      conversationId: json['conversationId'] as String,      contactId: json['contactId'] as String,      contactName: json['contactName'] as String,      lastMessage: json['lastMessage'] as String,      lastMessageTime: DateTime.parse(json['lastMessageTime'] as String),      unreadCount: json['unreadCount'] as int? ?? 0,      channel: json['channel'] as String? ?? 'ble',    );  }  Map<String, dynamic> toJson() => {    'conversationId': conversationId,    'contactId': contactId,    'contactName': contactName,    'lastMessage': lastMessage,    'lastMessageTime': lastMessageTime.toIso8601String(),    'unreadCount': unreadCount,    'channel': channel,  };  /// Human-readable time  String get timeText {    final diff = DateTime.now().difference(lastMessageTime);    if (diff.inSeconds < 60) return 'Now';    if (diff.inMinutes < 60) return '${diff.inMinutes}m';    if (diff.inHours < 24) return '${diff.inHours}h';    return '${diff.inDays}d';  }}